                                    {t.into_iter().map(|line| view! {
                                        <li><strong>{line.role}</strong><pre class="m-0 whitespace-pre-wrap">{line.text}</pre></li>
                                    }).collect_view()}
                                </ol>
                            </details>
                        })}
                    </div>
                })}
            </details>
        </li>
    }
