    fn records_chain_in_order_under_the_key() {
        let store = Arc::new(FakeStore::default());
        let log = AuditLog::start(store.clone(), b"k".to_vec(), WRITE_LIMIT);
        log.note(record("one"));
        log.note(record("two"));
